import{_ as e,c as a,o as r,b0 as d}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/image-20251222095539237.D0bxCy4e.png",o="/media-docs/assets/image-20251222102940599.D49eqSdG.png",l="/media-docs/assets/image-20251222102614325.NNl497Mi.png",i="/media-docs/assets/0843710678975cc4dd80f7abee87c3f3.Bb6SmhpP.png",c="/media-docs/assets/57874966eb2326997af99412bebaa71c.DDZkVHN_.png",D=JSON.parse('{"title":"LV005-概述","description":null,"frontmatter":{"title":"LV005-概述","date":"2025-12-20T11:52:42.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/acodec/atransmission/126b1ac7ff2a2740523bf3f1","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-20T11:52:42.628Z","fulluuid":"0523bf3f1ccf40139dc3302b7b9c1ba3","useduuid":"0523bf3f1"}},"headers":[],"relativePath":"sdoc/acodec/atransmission/126b1ac7ff2a2740523bf3f1.md","filePath":"sdoc/25-音频编解码/30-音频传输/LV005-概述.md","lastUpdated":1767537778000}'),s={name:"sdoc/acodec/atransmission/126b1ac7ff2a2740523bf3f1.md"};function p(h,t,g,f,b,_){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="lv005-概述" tabindex="-1">LV005-概述 <a class="header-anchor" href="#lv005-概述" aria-label="Permalink to &quot;LV005-概述&quot;">​</a></h1><h2 id="一、audio-codec" tabindex="-1">一、Audio CODEC <a class="header-anchor" href="#一、audio-codec" aria-label="Permalink to &quot;一、Audio CODEC&quot;">​</a></h2><h3 id="_1-为何需要音频编解码芯片" tabindex="-1">1. 为何需要音频编解码芯片？ <a class="header-anchor" href="#_1-为何需要音频编解码芯片" aria-label="Permalink to &quot;1. 为何需要音频编解码芯片？&quot;">​</a></h3><p>处理器要想“听到”外界的声音必须要把外界的声音转化为自己能够理解的“语言”，处理器能理解的就是 0 和 1，也就是二进制数据。 所以我们需要先把外界的声音转换为处理器能理解的 0 和 1，在信号处理领域，外界的声音是模拟信号，处理器能理解的是数字信号，因此这里就涉及到一个 <strong>模拟信号转换为数字信号</strong> 的过程，而完成这个功能的就是 ADC 芯片。</p><p>同理，如果处理器要向外界传达自己的“心声”，也就是放音，那么就涉及到将处理器能理解的 0 和 1 转化为外界能理解的连续变化的声音， 这个过程就是将数字信号转化为模拟信号，而完成这个功能的是 DAC 芯片。</p><p>现在我们知道了，处理器如果既想“听到”外界的声音，又想向外界传达自己的“心声”，那么就需要同时用到 DAC 和 ADC 这两款芯片。那是不是买两颗 DAC 和 ADC 芯片就行了呢？答案肯定是可以的，但是音频不单单是能出声、能听到就行。我们往往需要听到的声音动听、录进去的语音贴近真实、可以调节音效、 对声音能够进行一些处理(需要 DSP 单元)、拥有统一的标准接口，方便开发等等。将这些针对声音的各种要求全部叠加到 DAC 和 ADC 芯片上，那么就会得到一个专门用于音频的芯片，也就是音频编解码芯片，英文名字就是 <strong>Audio CODEC</strong>，所以我们在手机或者电脑的介绍中看到“CODEC”这个词语，一般说的都是 <strong>音频编解码</strong>。</p><p>既然音频 CODEC 的本质是 ADC 和 DAC，那么采样率和采样位数就是衡量一款音频 CODEC 最重要的指标。比如常见音频采样率有 8K、 44.1K、 48K、 192K 甚至 384K 和 768K，采样位数常见的有 8 位、 16 位、 24 位、 32 位。采样率和采样位数越高，那么音频 CODEC 越能真实的还原声音，也就是常说的 HIFI（High-Fidelit，翻译为“高保真”）。因此会看到高端的音频播放器都会有很高的采样率和采样位数，同样的价格也会越高。当然，实际的效果还与其他部分有关，采样率和采样位数只是其中重要的指标之一。</p><h3 id="_2-常见音频解码芯片" tabindex="-1">2. 常见音频解码芯片 <a class="header-anchor" href="#_2-常见音频解码芯片" aria-label="Permalink to &quot;2. 常见音频解码芯片&quot;">​</a></h3><h4 id="_2-1-wm8960" tabindex="-1">2.1 WM8960 <a class="header-anchor" href="#_2-1-wm8960" aria-label="Permalink to &quot;2.1 WM8960&quot;">​</a></h4><p>来看一款音频编解码芯片（ WM8960，这个是正点原子 imx6ull-alpha 开发板上的），简单了解一下。</p><p><a href="https://datasheets.ibselectronics.com/WM8960CGEFL-RV-Cirrus-Logic-datasheet-25356024.pdf" target="_blank" rel="noreferrer">WM8960</a> 是一颗由 <a href="https://www.ibselectronics.cn/" target="_blank" rel="noreferrer">wolfson(欧胜)</a> 公司出品的音频编解码芯片，是一颗低功耗、高质量的立体声音频 CODEC。集成 D 类喇叭功放，每个通道可以驱动一个 1W 喇叭(8Ω )。内部集成 3 个立体声输入源，可以灵活配置，拥有一路完整的麦克风接口。 WM8960 内部 ADC 和 DAC 都为 24 位。</p><p>具体特点就不详细说了，可以看芯片手册<a href="https://datasheets.ibselectronics.com/WM8960CGEFL-RV-Cirrus-Logic-datasheet-25356024.pdf" target="_blank" rel="noreferrer">WM8960_DS _DATASHEET</a>。WM8960 主要就是可以直接外接喇叭， 8Ω 负载下每通道 1W、集成耳机接口、麦克风接口，采样率支持 8K、 11.025K、 12K、 16K、 22.05K、 24K、 32K、 44.1K 和 48K。整体框图如图 所示：</p><p><img src="'+n+'" alt="image-20251222095539237"></p><p>①、此部分是 WM8960 提供的输入接口，作为立体声音频输入源，一共提供了三路，分别为 LINPUT1/RINPUT1、 LINPUT2/RINPUT2、 LINPUT3/RINPUT3。麦克风或线路输入就连接到此接口上，这部分是需要硬件工程师重点关心的，因为音频选择从哪一路进入需要在画 PCB 的时候就应该定好。</p><p>②、此部分是 WM8960 的输出接口，比如输出给耳机或喇叭， SPK_LP/SPK_LN 用于连接左声道的喇叭，支持 1W 的 8Ω 喇叭。 SPK_RP/SPK_RN 用于连接右声道的喇叭，同样支持 1W 的 8Ω 喇叭，最后就是 HP_L/HP_R，用于连接耳机。</p><p>③、此部分是数字音频接口，用于和主控制器连接，有 5 根线，用于主控制器和 WM8960 之间进行数据“沟通”。主控制器向 WM8960 的 DAC 发送的数据， WM8960 的 ADC 向主控制传递的数据都是通过此音频接口来完成的。这个接口非常重要，是驱动开发人员需要重点关注的，此接口支持 I2S 格式。</p><h4 id="_2-2-ak4458" tabindex="-1">2.2 AK4458 <a class="header-anchor" href="#_2-2-ak4458" aria-label="Permalink to &quot;2.2 AK4458&quot;">​</a></h4><p>这里也有一款，可以作为参考：<a href="https://www.akm.com/cn/zh-cn/products/audio/audio-dac/ak4458vn/" target="_blank" rel="noreferrer">AK4458</a></p><h3 id="_3-内置-codec" tabindex="-1">3. 内置 codec <a class="header-anchor" href="#_3-内置-codec" aria-label="Permalink to &quot;3. 内置 codec&quot;">​</a></h3><p>有一些芯片可能会内置音频的 codec，这样就可以直接直接采集音频信号，例如 RK3568 这种：</p><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="'+o+'" style="width:80%;height:auto;"></td><td align="center" style="border:none;"><img src="'+l+'" style="width:80%;height:auto;"></td></tr></tbody></table><blockquote><p>参考：<a href="https://gitee.com/rockchip-dev/document/raw/master/RockChip%E5%AE%98%E6%96%B9%E6%96%87%E6%A1%A3/Rockchip_RK3568_Datasheet_V1.3-20220929P.pdf" target="_blank" rel="noreferrer">Rockchip_RK3568_Datasheet_V1.3-20220929P.pdf</a></p></blockquote><h2 id="二、数字音频接口" tabindex="-1">二、数字音频接口 <a class="header-anchor" href="#二、数字音频接口" aria-label="Permalink to &quot;二、数字音频接口&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p><strong>数字音频 DAI</strong>，即 Digital Audio Interfaces。DAI 表示在板级或板间传输数字音频信号的方式。相比于模拟接口，数字音频接口抗干扰能力更强，硬件设计简单，DAI 在音频电路设计中得到越来越广泛的应用。</p><p>在传统的音频电路（图 1）中有麦克风、前置放大器、模/数转换器 ADC、数/模转换器 DAC、输出放大器，以及扬声器，它们之间使用模拟信号连接。随着技术的发展和对性能考虑，模拟电路逐渐被推到链路的两端（集成到设备内部），信号链中各集成电路间将出现更多的数字接口形式。DSP 通常都是数字接口的；换能器（Transducers, i.e. Mic &amp; Speaker）、放大器一般而言只有模拟接口，但现在也正在逐渐集成数字接口功能。 目前，集成电路设计人员正在将换能器内的 ADC、DAC 和调制器集成到信号链一端，这样就不必在 PCB 上走任何模拟音频信号，并且减少了信号链中的器件数量。图 2 给出了一个完整数字音频接口的例子。</p><img src="'+i+'" alt="img" style="zoom:80%;"><p align="center"> 图 1 传统音频信号链路 </p><img src="'+c+'" alt="img" style="zoom:80%;"><p align="center"> 图 2 数字音频信号链路 </p><h3 id="_2-传输标准" tabindex="-1">2. 传输标准 <a class="header-anchor" href="#_2-传输标准" aria-label="Permalink to &quot;2. 传输标准&quot;">​</a></h3><p>数字音频信号的传输标准包括 <strong>I2S、SAI、TDM、PDM</strong> 等。</p><table><tbody><tr><td align="center" width="150px"> 总线名称 </td> <td align="center" width="200px"> 全称 </td> <td align="center"> 应用场景 </td> <td align="center"> 说明 </td></tr><tr><td align="center"> PCM </td> <td align="center"> Pulse Code Modulation, 脉冲编码调制 </td> <td align="left"> 传输单声道数据，通常用于 AP 处理器和通信 MODEM 之间的语音数据传输（就是双向打电话的数据），也多用于蓝牙单声道通话传输。</td> <td align="left"> 这里的 PCM 指通信协议，主要是传送语音，经常看到的其实是 PCM/TDM，和 I2S 差不多，4 根线 </td></tr><tr><td align="center"> I2S </td> <td align="center"> Integrated Interchip Sound，IC 间音频 </td> <td align="left"> 单组 I2S 传输双声道数据，或者多组 I2S 传输多声道数据（Nx2），I2S 只能传 2 个声道的数据 </td> <td align="left"> I2S 总线兼容性最好，几乎所有的芯片都支持标准 I2S 接口 </td></tr><tr><td align="center"> TDM </td> <td align="center"> Time Division Multiplexing, 时分复用 </td> <td align="left"> 可以传输多达 16 路及以上音频数据，像现在最流行的语音智能音箱的 7 麦克风矩阵，一般都是用 TDM 来传的数据，同时可以传输 7 路麦克风输入和 3 路以上的音频反馈信号 </td> <td align="left"> PCM 可以传多达 16 路数据，采用时分复用的方式，就是 TDM, 常见的说法其实是 PCM/TDM，网上资料多数都是两者一起出现 </td></tr><tr><td align="center"> PDM </td> <td align="center"> Pulse Density Modulation, 脉冲密度调制 </td> <td align="left"> 通常用于数字硅麦与 SoC 连接，一个总线可以接多个器件 </td> <td align="left"> PDM 只有 2 根线 </td></tr><tr><td align="center"> Intel HDA </td> <td align="center"> Intel High Definition Audio </td> <td align="left"> 用于 PC 的 Audio 子系统（声卡）应用 </td> <td align="left"></td></tr><tr><td align="center"> S/PDIF </td> <td align="center"> Sony/Philips Digital Interconnect Format </td> <td align="left"> 是由索尼与飞利浦公司联合开发的民用数字音频接口协议，主要应用于板间长距离及需要电缆连接的场合。</td> <td align="left"></td></tr><tr><td align="center"> Ethernet AVB </td> <td align="center"> Audio Video Bridging，又称音频视频桥接技术 </td> <td align="left"> AVB 是基于车载以太网通信，处理音频和视频流比较常用的一种方式。以太网音视频桥接技术（Ethernet AVB）通过在传统以太网的基础上新增一系列协议标准，能提供高质量的音视频传输服务，以支持各种多媒体应用的通信需求。Ethernet AVB 主要用于音视频信息和控制类信息的数据传输。</td> <td align="left"></td></tr></tbody></table><blockquote><p>注意：在应用 PCM 音频接口传输单声道数据（如麦克风）时，其接口名称常为 <strong>PCM</strong>；双声道经常使用 <strong>I2S</strong>；而 <strong>TDM</strong> 则表示传输两个及以上声道的数据，同时区别于 I2S 特定的格式。</p></blockquote><h2 id="三、总结" tabindex="-1">三、总结 <a class="header-anchor" href="#三、总结" aria-label="Permalink to &quot;三、总结&quot;">​</a></h2><p>音频系统大概需要关注三层内容：</p><table><tbody><tr><td> 类别 </td><td> 音频术语 </td><td> 类比解释 </td></tr><tr><td> 硬件接口 </td><td> I2S / SAI 控制器 </td><td> 快递公司（谁来送）</td></tr><tr><td> 协议 </td><td> PCM / I2S / TDM / PDM / SPDIF </td><td> 快递方式（怎么送）</td></tr><tr><td> 数据格式 </td><td> PCM / ADPCM / PDM / AC3 </td><td> 包裹内容（送什么）</td></tr><tr><td> SLOT（TDM）</td><td> 时间片/通道 </td><td> 快递车的货架格子（每格一个通道）</td></tr></tbody></table><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/Interview_TC/article/details/146317932" target="_blank" rel="noreferrer">深入解析音频编解码器（Audio CODEC）：硬件、接口与驱动开发-CSDN 博客</a></p><p><a href="https://blog.csdn.net/zhuwade/article/details/121793160" target="_blank" rel="noreferrer">数字音频接口(I2S, PCM/TDM, PDM)_pdm 接口-CSDN 博客</a></p><p><a href="https://blog.51cto.com/u_16213571/14380364" target="_blank" rel="noreferrer">【精华贴】数字音频接口详解-I2S 接口&amp;PCM/TDM 接口&amp;PDM 接口_mob64ca13f53d41 的技术博客_51CTO 博客</a></p><p><a href="https://blog.csdn.net/zhangchao0426/article/details/105367754" target="_blank" rel="noreferrer">常用音频接口：TDM，PDM，I2S，PCM_pdm tdm-CSDN 博客</a></p></blockquote>',38)])])}const m=e(s,[["render",p]]);export{D as __pageData,m as default};
